class UserPagingSource(private val api: UserApi) : PagingSource<Int, User>() {
    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, User> {
        val page = params.key ?: 1
        val response = api.getUsers(page = page, size = params.loadSize)
        return LoadResult.Page(response.users, prevKey = if (page == 1) null else page - 1, nextKey = if (response.users.isEmpty()) null else page + 1)
    }
    override fun getRefreshKey(state: PagingState<Int, User>) = null
}

class ArticlesViewModel(repository: ArticleRepository) : ViewModel() {
    val articles: Flow<PagingData<Article>> =
        Pager(PagingConfig(pageSize = 20)) { repository.articlesPagingSource() }
            .flow
            .map { pagingData -> pagingData.map { it.toUi() } }
            .cachedIn(viewModelScope)   // last step
}

val items = viewModel.articles.collectAsLazyPagingItems()

when (val refresh = items.loadState.refresh) {
    is LoadState.Loading -> FullScreenSpinner()
    is LoadState.Error -> ErrorMessage(refresh.error, onRetry = { items.retry() })
    else -> LazyColumn {
        items(count = items.itemCount, key = items.itemKey { it.id }) { index ->
            items[index]?.let { ArticleRow(it) }
        }
        if (items.loadState.append is LoadState.Loading) item { FooterSpinner() }
    }
}

@OptIn(ExperimentalPagingApi::class)
class ArticleRemoteMediator(
    private val api: ArticleApi,
    private val db: AppDatabase
) : RemoteMediator<Int, ArticleEntity>() {

    override suspend fun load(
        loadType: LoadType,
        state: PagingState<Int, ArticleEntity>
    ): MediatorResult {
        val page = when (loadType) {
            LoadType.REFRESH -> 1
            LoadType.PREPEND -> return MediatorResult.Success(endOfPaginationReached = true)
            LoadType.APPEND -> db.remoteKeysDao().nextPage() ?: return MediatorResult.Success(true)
        }
        return try {
            val items = api.articles(page = page, size = state.config.pageSize)
            db.withTransaction {
                if (loadType == LoadType.REFRESH) db.articleDao().clearAll()
                db.articleDao().insertAll(items.map { it.toEntity() })
                db.remoteKeysDao().save(nextPage = page + 1)
            }
            MediatorResult.Success(endOfPaginationReached = items.isEmpty())
        } catch (e: IOException) {
            MediatorResult.Error(e)
        }
    }
}
